package ru.neverland.townycompanies;
import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.io.*;
import static ru.neverland.townycompanies.CompanyData.*;
public final class CompanyPayrollSmoke {
 static int checks;static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static <T>T await(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(10,TimeUnit.SECONDS);}interface Action{void run()throws Exception;}static void fails(Action f)throws Exception{try{f.run();}catch(Exception expected){checks++;return;}throw new AssertionError();}
 static class Store implements CompanyLedger.Store {CompanyLedger.State state=CompanyLedger.State.empty();boolean fail;public CompanyLedger.State state(){return state;}public boolean writable(){return !fail;}public void save(CompanyLedger.State n)throws IOException{if(fail)throw new IOException("disk full");state=n;}}
 public static void main(String[] args)throws Exception{Path dir=Files.createTempDirectory("payroll-real-sqlite");UUID company=UUID.randomUUID(),owner=UUID.randomUUID(),town=UUID.randomUUID(),worker=UUID.randomUUID();var sql=new CompanyPayrollStore(dir.resolve("salary.sqlite"),ex->{throw new AssertionError(ex);});await(sql.ready());check(!sql.settings(company).enabled(),"companies default to opt-in");await(sql.configure(new CompanyPayrollStore.Settings(company,true,300,Map.of("farmer",100L),1),0));long now=System.currentTimeMillis();var multipliers=List.of(1.,1.05,1.1,1.15,1.2);UUID proof=UUID.randomUUID();check(await(sql.offer(proof,company,worker,"farmer",5,now,multipliers)),"verified action persisted");check(sql.outstanding().get(0).cents()==120,"level rate exact cents");check(!await(sql.offer(proof,UUID.randomUUID(),worker,"farmer",5,now,multipliers)),"proof cannot move to another employer");check(await(sql.offer(UUID.randomUUID(),company,worker,"farmer",5,now,multipliers)),"second budget reservation");check(!await(sql.offer(UUID.randomUUID(),company,worker,"farmer",5,now,multipliers)),"rolling budget includes queued and review money");await(sql.state(proof,"REVIEW"));check(!await(sql.offer(UUID.randomUUID(),company,worker,"farmer",5,now,multipliers)),"uncertain payment retains budget");await(sql.state(proof,"REJECTED"));check(await(sql.offer(UUID.randomUUID(),company,worker,"farmer",5,now,multipliers)),"definitive rejection restores budget");fails(()->await(sql.configure(new CompanyPayrollStore.Settings(company,false,100,Map.of(),1),0)));await(sql.configure(new CompanyPayrollStore.Settings(company,false,300,Map.of("farmer",100L),2),1));check(!await(sql.offer(UUID.randomUUID(),company,worker,"farmer",1,now,multipliers)),"pause prevents new wages");check(!sql.outstanding().isEmpty(),"pause preserves earned obligations");var history=await(sql.history(company));check(history.size()==3,"durable immutable work history");sql.close();
 var reopened=new CompanyPayrollStore(dir.resolve("salary.sqlite"),ex->{throw new AssertionError(ex);});await(reopened.ready());check(!reopened.settings(company).enabled()&&await(reopened.history(company)).equals(history),"restart restores settings and receipt states");reopened.close();
 var store=new Store();final int[] calls={0};final boolean[] ambiguous={true};var ledger=new CompanyLedger(store,p->{calls[0]++;if(ambiguous[0])throw new IOException("lost reply");return true;});ledger.put(new Company(company,town,"Компания",Kind.FARM,owner,Map.of(owner,Role.OWNER,worker,Role.WORKER),Map.of(),null,0,1000,0,now+10000,0,false));var pay=ledger.begin(proof,company,worker,Purpose.SALARY,120,now);check(ledger.company(company).balance()==880,"salary reserves employer money");ledger.process(pay.id());check(store.state.payments().get(proof).phase()==Phase.PENDING,"unknown bank result held");ledger=new CompanyLedger(store,p->{calls[0]++;return true;});check(ledger.begin(proof,company,worker,Purpose.SALARY,120,now).phase()==Phase.PENDING,"replay binds same UUID");ledger.process(proof);check(calls[0]==1&&ledger.company(company).balance()==880,"restart never pays twice");ledger.finish(proof,false);check(ledger.company(company).balance()==1000,"rejected wage returns all employer money");UUID accepted=UUID.randomUUID();ledger.begin(accepted,company,worker,Purpose.SALARY,120,now);ledger.process(accepted);check(ledger.company(company).balance()==880&&calls[0]==2,"single completed wage deducted once");ledger.begin(accepted,company,worker,Purpose.SALARY,120,now);ledger.process(accepted);check(calls[0]==2&&ledger.company(company).balance()==880,"terminal replay does not debit or pay");var finalLedger=ledger;fails(()->finalLedger.begin(accepted,company,worker,Purpose.SALARY,121,now));store.fail=true;int before=calls[0];fails(()->finalLedger.begin(UUID.randomUUID(),company,worker,Purpose.SALARY,100,now));check(calls[0]==before&&finalLedger.company(company).balance()==880,"no bank mutation on failed durable reservation");System.out.println("CompanyPayrollSmoke PASS: "+checks+" SQLite, budget, rate, restart, conservation and ambiguity assertions"); }
}
